CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "UserRole" AS ENUM ('CUSTOMER','DEMO_OPERATOR','ADMIN');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','DISABLED');
CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE','FROZEN','CLOSED');
CREATE TYPE "LedgerNormalSide" AS ENUM ('DEBIT','CREDIT');
CREATE TYPE "TransactionType" AS ENUM ('TRANSFER','DEPOSIT','WITHDRAWAL','REVERSAL');
CREATE TYPE "TransactionStatus" AS ENUM ('POSTED');
CREATE TYPE "IdempotencyStatus" AS ENUM ('RESERVED','POSTED','REJECTED');
CREATE TYPE "AttemptOutcome" AS ENUM ('POSTED','BUSINESS_REJECTED','IDEMPOTENT_REPLAY','IDEMPOTENCY_CONFLICT','VALIDATION_REJECTED','PROCESSING_ERROR');
CREATE TYPE "SessionStatus" AS ENUM ('ACTIVE','REVOKED');
CREATE TYPE "RefreshStatus" AS ENUM ('CURRENT','ROTATED','REVOKED');
CREATE TYPE "ReconciliationStatus" AS ENUM ('RUNNING','COMPLETED','FAILED');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(100) NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role "UserRole" NOT NULL DEFAULT 'CUSTOMER',status "UserStatus" NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),current_refresh_hash text NOT NULL,status "SessionStatus" NOT NULL DEFAULT 'ACTIVE',expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refresh_token_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES user_sessions(id),token_hash text NOT NULL UNIQUE,status "RefreshStatus" NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),rotated_at timestamptz);
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES users(id),account_number varchar(14) NOT NULL UNIQUE,currency char(3) NOT NULL DEFAULT 'INR',status "AccountStatus" NOT NULL DEFAULT 'ACTIVE',balance_minor bigint NOT NULL DEFAULT 0 CHECK(balance_minor>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid UNIQUE REFERENCES accounts(id),code text UNIQUE,normal_side "LedgerNormalSide" NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',currency char(3) NOT NULL DEFAULT 'INR',CHECK ((account_id IS NULL) <> (code IS NULL)));
CREATE TABLE transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),type "TransactionType" NOT NULL,status "TransactionStatus" NOT NULL DEFAULT 'POSTED',amount_minor bigint NOT NULL CHECK(amount_minor>0),currency char(3) NOT NULL,description varchar(250),initiated_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),posted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_id uuid NOT NULL REFERENCES transactions(id),ledger_account_id uuid NOT NULL REFERENCES ledger_accounts(id),direction text NOT NULL CHECK(direction IN ('DEBIT','CREDIT')),amount_minor bigint NOT NULL CHECK(amount_minor>0),currency char(3) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_entries_account_idx ON ledger_entries(ledger_account_id);
CREATE TABLE idempotency_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES users(id),operation text NOT NULL,key varchar(128) NOT NULL,fingerprint text NOT NULL,status "IdempotencyStatus" NOT NULL,response jsonb,http_status int,transaction_id uuid REFERENCES transactions(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(principal_id,operation,key));
CREATE TABLE transaction_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),principal_id uuid NOT NULL REFERENCES users(id),operation text NOT NULL,outcome "AttemptOutcome" NOT NULL,reason_code text,amount_minor bigint,correlation_id text NOT NULL,transaction_id uuid REFERENCES transactions(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX attempts_principal_created_idx ON transaction_attempts(principal_id,created_at DESC);
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id uuid REFERENCES users(id),action text NOT NULL,target_type text,target_id text,metadata jsonb NOT NULL DEFAULT '{}',correlation_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE system_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),started_by uuid NOT NULL REFERENCES users(id),status "ReconciliationStatus" NOT NULL,snapshot_started_at timestamptz NOT NULL,consistency_mode text NOT NULL,customer_account_count int NOT NULL DEFAULT 0,system_account_count int NOT NULL DEFAULT 0,discrepancy_count int NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'INR',started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,failure_code text);
CREATE TABLE reconciliation_discrepancies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES reconciliation_runs(id),code text NOT NULL,details jsonb NOT NULL);
INSERT INTO ledger_accounts(code,normal_side,currency) VALUES ('DEMO_CASH_CLEARING','DEBIT','INR');
INSERT INTO system_settings(key,value) VALUES ('DEMO_FUNDING_ENABLED','true'::jsonb);
CREATE OR REPLACE FUNCTION ledger_entries_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'LEDGER_ENTRIES_APPEND_ONLY'; END $$;
CREATE TRIGGER ledger_entries_no_update_delete BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION ledger_entries_immutable();
CREATE TRIGGER ledger_entries_no_truncate BEFORE TRUNCATE ON ledger_entries FOR EACH STATEMENT EXECUTE FUNCTION ledger_entries_immutable();
CREATE OR REPLACE FUNCTION check_posted_transaction_balance() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE tid uuid; debit_total numeric; credit_total numeric; n int; BEGIN tid := COALESCE(NEW.transaction_id, OLD.transaction_id); SELECT count(*),COALESCE(sum(amount_minor) FILTER(WHERE direction='DEBIT'),0),COALESCE(sum(amount_minor) FILTER(WHERE direction='CREDIT'),0) INTO n,debit_total,credit_total FROM ledger_entries WHERE transaction_id=tid; IF n<2 OR debit_total<>credit_total THEN RAISE EXCEPTION 'UNBALANCED_LEDGER_TRANSACTION %',tid; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER ledger_balance_at_commit AFTER INSERT OR UPDATE ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_posted_transaction_balance();
CREATE OR REPLACE FUNCTION no_reserved_idempotency_at_commit() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE current_status "IdempotencyStatus"; BEGIN SELECT status INTO current_status FROM idempotency_records WHERE id=NEW.id; IF current_status='RESERVED' THEN RAISE EXCEPTION 'COMMITTED_RESERVED_IDEMPOTENCY'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER idempotency_finalized_at_commit AFTER INSERT OR UPDATE ON idempotency_records DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION no_reserved_idempotency_at_commit();

CREATE OR REPLACE FUNCTION check_ledger_currency() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE tx_currency char(3); ledger_currency char(3); BEGIN SELECT currency INTO tx_currency FROM transactions WHERE id=NEW.transaction_id; SELECT currency INTO ledger_currency FROM ledger_accounts WHERE id=NEW.ledger_account_id; IF tx_currency IS NULL OR ledger_currency IS NULL OR NEW.currency<>tx_currency OR NEW.currency<>ledger_currency THEN RAISE EXCEPTION 'LEDGER_CURRENCY_MISMATCH'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER ledger_currency_consistency AFTER INSERT OR UPDATE ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_ledger_currency();
